import{_ as e,o as i,c as r,a2 as o}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Habilidades y progresión","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/characters/progression.md","filePath":"es/guide/characters/progression.md"}'),s={name:"es/guide/characters/progression.md"};function t(n,a,d,c,l,p){return i(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="skills-progression" tabindex="-1">Habilidades y progresión <a class="header-anchor" href="#skills-progression" aria-label="Enlace permanente a &quot;Habilidades y progresión&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · Disponibilidad no confirmada.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Un personaje inexperto ya debería resultar útil.</li><li>Progresa mediante habilidad del personaje, conocimientos aprendidos y ejecución del jugador.</li><li>La especialización, el descubrimiento y la reputación ofrecen metas más allá de maximizar habilidades.</li></ul><p><span id="character-progression"></span><span id="useful-from-the-first-day"></span><span id="three-ways-to-grow"></span><span id="a-build-with-tradeoffs"></span><span id="more-than-one-endgame"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elemento</th><th>Qué significa para el jugador</th></tr></thead><tbody><tr><td>Skill (habilidad)</td><td>Mejora la capacidad, la consistencia y la dificultad que puedes afrontar.</td></tr><tr><td>Conocimiento</td><td>Abre técnicas, procesos e información que merece la pena descubrir.</td></tr><tr><td>Ejecución del jugador</td><td>Da valor al criterio, la posición y la comprensión práctica.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Orientación de Syrolands</th></tr></thead><tbody><tr><td>Un presupuesto compartido de habilidades favorece distintas configuraciones.</td><td>Se conserva un presupuesto, dando utilidad a habilidades de apoyo y de baja inversión junto a las especialidades.</td></tr><tr><td>Las habilidades de gran maestro son una meta conocida; épocas posteriores también ofrecen límites mayores.</td><td>El objetivo normal es 100, sin una progresión habitual a 120; el conocimiento puede seguir creciendo.</td></tr></tbody></table><p>Las reglas de UO varían según la época y el shard. <a href="https://uo.com/wiki/ultima-online-wiki/items/scrolls-of-power/" target="_blank" rel="noreferrer">UO oficial: Scrolls of Power</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Dos cazadores hábiles podrían conocer técnicas distintas. Uno se hace conocido por rastrear presas peligrosas; otro combina la caza con equipo de campo duradero y una red comercial.</p><h2 id="progression-trade-offs" tabindex="-1">Progresión y contrapartidas <a class="header-anchor" href="#progression-trade-offs" aria-label="Enlace permanente a &quot;Progresión y contrapartidas&quot;">​</a></h2><p>La orientación de unos 700 puntos debería permitir especialidades principales, habilidades de apoyo y pequeñas inversiones de utilidad. Ni siete habilidades maximizadas ni una distribución uniforme pretenden ser siempre la mejor opción.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/characters/skills.html">Límite de habilidades y maestros</a> · <a href="/Syrolands-Public/es/guide/characters/character-creation.html">Creación del personaje</a> · <a href="/Syrolands-Public/es/guide/professions/overview.html">Profesiones</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p>Consulta la especificación de diseño: <a href="/Syrolands-Public/es/game-design/characters/progression.html">Habilidades y progresión</a>.</p>',18)])])}const m=e(s,[["render",t]]);export{u as __pageData,m as default};
